        span.setAttribute("aria-hidden", "true");
        return span;
      }

      function OptionalBadge() {
        const span = document.createElement("span");
        span.className = "optional-badge";
        span.textContent = "(optional)";
        return span;
      }

      function FormField({ id, labelText, type = "text", placeholder, required, helperText, validate }) {
        const wrapper = document.createElement("div");
        wrapper.className = "form-field";

        const lbl = document.createElement("label");
        lbl.htmlFor = id;
        lbl.textContent = labelText;
        if (required) lbl.appendChild(RequiredMark());
        else lbl.appendChild(OptionalBadge());

        const input = document.createElement("input");
        input.type = type;
        input.id = id;
        input.name = id;
        input.placeholder = placeholder || "";
        input.setAttribute("autocomplete", id === "email" ? "email" : id === "fullname" ? "name" : "tel");

        const validationMsg = document.createElement("div");
        validationMsg.className = "validation-message";
        validationMsg.id = `${id}-error`;
        validationMsg.setAttribute("role", "alert");
        validationMsg.setAttribute("aria-live", "polite");

        function showError(msg) {
          input.classList.add("is-invalid");
          input.classList.remove("is-valid");
          validationMsg.className = "validation-message error";
          validationMsg.textContent = msg;
          input.setAttribute("aria-describedby", `${id}-error`);
          input.setAttribute("aria-invalid", "true");
        }

        function clearError() {
          input.classList.remove("is-invalid");
          if (input.value.trim()) input.classList.add("is-valid");
          validationMsg.className = "validation-message";
          validationMsg.textContent = "";
          input.removeAttribute("aria-invalid");
        }

        input.addEventListener("blur", () => {
          const result = validate(input.value);
          if (result) showError(result);
          else clearError();
        });

        input.addEventListener("input", () => {
          if (input.classList.contains("is-invalid")) {
            const result = validate(input.value);
            if (!result) clearError();
          }
        });

        // expose for submit validation
        input._validate = validate;
        input._showError = showError;
        input._clearError = clearError;

        wrapper.appendChild(lbl);
        wrapper.appendChild(input);

        if (helperText) {
          const helper = document.createElement("p");
          helper.className = "helper-text";
          helper.textContent = helperText;
          wrapper.appendChild(helper);
        }

        wrapper.appendChild(validationMsg);
        return { node: wrapper, input };
      }

      function ContactForm() {
        const card = document.createElement("div");
        card.className = "card";

        // Header
        const header = document.createElement("div");
        header.className = "card-header";
        const h1 = document.createElement("h1");
        h1.textContent = "Contact Support";
        const subtitle = document.createElement("p");
        subtitle.textContent = "Fill out the form below and we'll get back to you as soon as possible.";
        header.appendChild(h1);
        header.appendChild(subtitle);

        // Form
        const form = document.createElement("form");
        form.noValidate = true;
        form.setAttribute("aria-label", "Support contact form");

        // Validators
        function validateFullName(value) {
          if (!value.trim()) return "Full name is required.";
          if (value.trim().length < 2) return "Please enter your full name (at least 2 characters).";
          return null;
        }

        function validateEmail(value) {
          if (!value.trim()) return "Email address is required.";
          const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRe.test(value.trim())) return "Please enter a valid email address.";
          return null;
        }

        function validatePhone(value) {
          if (!value.trim()) return null; // optional
          const phoneRe = /^\+?[\d\s\-().]{7,20}$/;
          if (!phoneRe.test(value.trim())) return "Phone number format is invalid. Use digits, spaces, dashes, or parentheses.";
          return null;
        }

        const { node: nameField, input: nameInput } = FormField({
          id: "fullname",
          labelText: "Full Name",
          placeholder: "Jane Smith",
          required: true,
          validate: validateFullName,
        });

        const { node: emailField, input: emailInput } = FormField({
          id: "email",
          labelText: "Email Address",
          type: "email",
          placeholder: "jane@example.com",
          required: true,
          validate: validateEmail,
        });

        const { node: phoneField, input: phoneInput } = FormField({
          id: "phone",
          labelText: "Phone Number",
          type: "tel",
          placeholder: "+1 (555) 000-0000",
          required: false,
          helperText: "Format: +1 (555) 000-0000 — include country code, area code, and number.",
          validate: validatePhone,
        });

        // Submit button
        const submitBtn = document.createElement("button");
        submitBtn.type = "submit";
        submitBtn.className = "submit-btn";
        submitBtn.textContent = "Send Message";

        // Success banner
        const successBanner = document.createElement("div");
        successBanner.className = "success-banner";
        successBanner.textContent = "✓ Your message has been sent! We'll be in touch shortly.";

        form.addEventListener("submit", (e) => {
          e.preventDefault();

          const fields = [
            { input: nameInput,  validate: validateFullName },
            { input: emailInput, validate: validateEmail },
            { input: phoneInput, validate: validatePhone },
          ];

          let hasError = false;
          fields.forEach(({ input, validate }) => {
            const result = validate(input.value);
            if (result) {
              input._showError(result);
              hasError = true;
            } else {
              input._clearError();
            }
          });

          if (!hasError) {
            form.style.display = "none";
            successBanner.style.display = "block";
          } else {
            // Focus first invalid field
            const firstInvalid = form.querySelector("input.is-invalid");
            if (firstInvalid) firstInvalid.focus();
          }
        });

        form.appendChild(nameField);
        form.appendChild(emailField);
        form.appendChild(phoneField);
        form.appendChild(submitBtn);

        card.appendChild(header);
        card.appendChild(form);
        card.appendChild(successBanner);

        return card;
      }

      // Mount
      document.getElementById("root").appendChild(ContactForm());
    </script>
